use std::sync::{
    atomic::{AtomicU64, Ordering},
    Mutex,
};

/// All values use logical screen points, including negative display origins.
pub fn clamped_origin(
    area: (f64, f64, f64, f64),
    size: (f64, f64),
    wanted: (f64, f64),
) -> (f64, f64) {
    let (left, top, width, height) = area;
    (
        wanted.0.clamp(left, left + (width - size.0).max(0.)),
        wanted.1.clamp(top, top + (height - size.1).max(0.)),
    )
}

/// Focus changes generated by activating a status-bar application can arrive
/// after the click that opened it. A newer action invalidates queued blur work.
#[derive(Default)]
pub struct PanelState {
    revision: AtomicU64,
    tray_press_visible: Mutex<Option<bool>>,
}

impl PanelState {
    pub fn invalidate(&self) -> u64 {
        self.revision.fetch_add(1, Ordering::SeqCst).wrapping_add(1)
    }

    pub fn is_current(&self, revision: u64) -> bool {
        self.revision.load(Ordering::SeqCst) == revision
    }

    pub fn tray_pressed(&self, visible: bool) {
        self.invalidate();
        *self.tray_press_visible.lock().unwrap() = Some(visible);
    }

    pub fn tray_released_should_hide(&self, visible: bool) -> bool {
        self.invalidate();
        self.tray_press_visible
            .lock()
            .unwrap()
            .take()
            .unwrap_or(visible)
    }
}

#[cfg(test)]
mod tests {
    use super::{clamped_origin, PanelState};

    #[test]
    fn offscreen_retina_panel_is_clamped_inside_actual_work_area() {
        // Observed screen: 1470x956 logical points at 2x; menu bar and Dock
        // leave the top-left work area (0,33,1470,859).
        assert_eq!(
            clamped_origin((0., 33., 1470., 859.), (500., 691.), (1627., 0.)),
            (970., 33.)
        );
    }

    #[test]
    fn placement_handles_negative_monitor_origins_and_small_screens() {
        assert_eq!(
            clamped_origin((-1920., 24., 1920., 1056.), (500., 690.), (100., -10.)),
            (-500., 24.)
        );
        assert_eq!(
            clamped_origin((100., 40., 400., 500.), (500., 690.), (-100., 1000.)),
            (100., 40.)
        );
    }

    #[test]
    fn showing_or_regaining_focus_cancels_stale_blur() {
        let panel = PanelState::default();
        let blur = panel.invalidate();
        panel.invalidate(); // show / focus gained
        assert!(!panel.is_current(blur));
    }

    #[test]
    fn only_latest_blur_may_hide_the_window() {
        let panel = PanelState::default();
        let first = panel.invalidate();
        let second = panel.invalidate();
        assert!(!panel.is_current(first));
        assert!(panel.is_current(second));
    }

    #[test]
    fn tray_release_uses_visibility_before_status_bar_takes_focus() {
        let panel = PanelState::default();
        panel.tray_pressed(true);
        // Native focus handling may have changed visibility between down and up.
        assert!(panel.tray_released_should_hide(false));
        panel.tray_pressed(false);
        assert!(!panel.tray_released_should_hide(true));
    }

    #[test]
    fn tray_interaction_cancels_pending_auto_hide() {
        let panel = PanelState::default();
        let blur = panel.invalidate();
        panel.tray_pressed(false);
        assert!(!panel.is_current(blur));
        assert!(!panel.tray_released_should_hide(false));
    }
}
